modern_c2_ds.program:
def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    jeep_patches = image_patch.find("jeep Cherokee")
    if not jeep_patches:
        return image_patch

    jeep_patch = jeep_patches[0]
    horse_patches = image_patch.find("horse")
    if not horse_patches:
        return jeep_patch

    jeep_center = jeep_patch.horizontal_center
    horse_centers = [h.horizontal_center for h in horse_patches]
    horse_centers.sort()

    for i, center in enumerate(horse_centers):
        if center > jeep_center:
            if i > 0 and abs(center - jeep_center) > abs(horse_centers[i-1] - jeep_center):
                return horse_patches[i-1]
            return horse_patches[i]

    return horse_patches[-1]

